counties.forEach(c=>{const o=document.createElement("option");o.value=c;o.textContent=c;countyFilter?.appendChild(o)});
function render(){if(!grid)return;const q=(search?.value||"").trim().toLowerCase(),co=countyFilter?.value||"",g=gender?.value||"",a=accom?.value||"";const list=schools.filter(s=>(!q||[s.name,s.county,s.uic,s.knec,s.subCounty,s.cluster].join(" ").toLowerCase().includes(q))&&(!co||s.county===co)&&(!g||s.gender===g)&&(!a||s.accommodation===a));const count=document.getElementById("finderCount");if(count)count.textContent=list.length.toLocaleString()+" C3 school records shown from the supplied list ("+schools.length.toLocaleString()+" total records).";grid.innerHTML=list.map(s=>'<article class="school-card"><div class="school-rank">'+s.cluster+' • '+s.county+'</div><h3>'+s.name+'</h3><div class="school-meta"><span>📍 '+s.county+'</span><span>👥 '+s.gender+'</span><span>🏫 '+s.accommodation+'</span></div><p><b>UIC:</b> '+(s.uic||"Not stated")+' &nbsp; <b>KNEC:</b> '+(s.knec||"Not stated")+'</p><p><b>Type:</b> '+s.type+' • '+s.status+' • Disability: '+s.disability+'</p><a class="profile-link" href="https://selection.education.go.ke/" target="_blank" rel="noopener">Verify official profile ↗</a></article>').join("")||'<div class="school-card"><h3>No matching C3 school</h3><p>Try another county or search term.</p></div>';}
[search,countyFilter,gender,accom].forEach(e=>e?.addEventListener("input",render));render();
